package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.linear.*;

/** Independently implemented adjusted-ECDF control functions (Liengaard et al., 2025).
 * Equations 9, 17 and 20–21; structural polynomials are supplied explicitly.
 */
public final class AdjustedCopula {
    private AdjustedCopula(){}
    public record Correction(int target,int[] endogenous,int[] continuousExogenous,int[] binaryExogenous,boolean varyingByCategory){
        public Correction{endogenous=endogenous.clone();continuousExogenous=continuousExogenous.clone();binaryExogenous=binaryExogenous.clone();Set<Integer> all=new HashSet<>();if(target<0||endogenous.length==0||binaryExogenous.length>4)throw new IllegalArgumentException("Select endogenous continuous variables and at most four binary covariates.");for(var values:List.of(endogenous,continuousExogenous,binaryExogenous))for(int value:values)if(value<0||value==target||!all.add(value))throw new IllegalArgumentException("Copula variable classifications must be disjoint, in range and different from the target.");}
        @Override public int[] endogenous(){return endogenous.clone();}
        @Override public int[] continuousExogenous(){return continuousExogenous.clone();}
        @Override public int[] binaryExogenous(){return binaryExogenous.clone();}
    }
    public record Model(List<String> names,List<PlsSem.Edge> paths,List<NonlinearPls.Extension> extensions,List<Correction> corrections,List<PathProcess.Probe> probes){
        public Model{names=List.copyOf(names);paths=List.copyOf(paths);extensions=List.copyOf(extensions);corrections=List.copyOf(corrections);probes=List.copyOf(probes);if(names.size()<2||names.size()>64||new HashSet<>(names).size()!=names.size()||names.stream().anyMatch(s->s==null||s.isBlank())||corrections.isEmpty()||corrections.size()>64||probes.size()>20)throw new IllegalArgumentException("Use 2–64 uniquely named variables, 1–64 corrected equations and at most 20 probes.");Set<Integer> targets=new HashSet<>();for(var c:corrections){if(c.target>=names.size()||!targets.add(c.target))throw new IllegalArgumentException("Corrected targets must be unique and in range.");for(var columns:List.of(c.endogenous,c.continuousExogenous,c.binaryExogenous))for(int column:columns)if(column>=names.size())throw new IllegalArgumentException("Copula variable index is out of range.");}}
    }
    public record Group(String label,int observations,double covarianceConditionNumber){}
    public record Controls(List<String> names,double[][] values,List<Group> groups){public Controls{names=List.copyOf(names);values=Matrices.copy(values);groups=List.copyOf(groups);}@Override public double[][] values(){return Matrices.copy(values);}}
    public record Equation(int target,List<NonlinearPls.Regressor> terms,Correction correction,double[] coefficients,double[] uncorrectedCoefficients,
                           Controls controls,int residualDegreesOfFreedom,double residualSumOfSquares,double rSquared,double adjustedRSquared,
                           double standardizedConditionNumber,double[] predictions,double[] residuals){
        public Equation{terms=List.copyOf(terms);coefficients=coefficients.clone();uncorrectedCoefficients=uncorrectedCoefficients.clone();predictions=predictions.clone();residuals=residuals.clone();if(coefficients.length!=terms.size()+1+controls.names.size()||uncorrectedCoefficients.length!=terms.size()+1||predictions.length!=residuals.length||residualDegreesOfFreedom!=predictions.length-coefficients.length||residualDegreesOfFreedom<=0||!Arrays.stream(coefficients).allMatch(Double::isFinite)||!Arrays.stream(uncorrectedCoefficients).allMatch(Double::isFinite)||!Arrays.stream(predictions).allMatch(Double::isFinite)||!Arrays.stream(residuals).allMatch(Double::isFinite)||!Double.isFinite(rSquared)||!Double.isFinite(adjustedRSquared)||!Double.isFinite(residualSumOfSquares)||residualSumOfSquares<0||!Double.isFinite(standardizedConditionNumber))throw new IllegalArgumentException("Invalid adjusted-copula equation archive.");}
        @Override public double[] coefficients(){return coefficients.clone();}
        @Override public double[] uncorrectedCoefficients(){return uncorrectedCoefficients.clone();}
        @Override public double[] predictions(){return predictions.clone();}
        @Override public double[] residuals(){return residuals.clone();}
    }
    public record Effect(String probe,String family,int source,int target,double value){}
    public record Fit(Model model,int observations,List<PlsSem.Edge> normalizedPaths,List<Equation> equations,List<Effect> effects,List<String> warnings){public Fit{normalizedPaths=List.copyOf(normalizedPaths);equations=List.copyOf(equations);effects=List.copyOf(effects);warnings=List.copyOf(warnings);if(observations<3||equations.isEmpty()||effects.size()>10000)throw new IllegalArgumentException("Invalid or excessive adjusted-copula result.");}}
    public record Resampled(Fit point,Bootstrap.Result inference,List<CopulaWald.Result> wald){public Resampled{wald=List.copyOf(wald);}}

    public static Fit fit(double[][] data,Model model){return refit(data,model,null);}
    static Fit refit(double[][] data,Model model,Fit reference){
        int width=Matrices.width(data,3);if(width!=model.names.size()||(long)data.length*width>5000000L)throw new IllegalArgumentException("Adjusted-copula data must match the variable names and fit within five million cells.");
        if(model.probes.isEmpty()){Map<Integer,Double> means=new LinkedHashMap<>();for(int column=0;column<width;column++){double mean=0;for(var row:data)mean+=row[column]/data.length;means.put(column,mean);}model=new Model(model.names,model.paths,model.extensions,model.corrections,List.of(new PathProcess.Probe("Observed means",means)));}
        var polynomial=NonlinearPls.fitScores(data,model.names,model.paths,new NonlinearPls.Specification(model.extensions,List.of(),null),false,false);
        Map<Integer,Correction> corrections=new HashMap<>();for(var correction:model.corrections)corrections.put(correction.target,correction);
        Set<Integer> binary=new HashSet<>();for(var correction:model.corrections)for(int col:correction.binaryExogenous)binary.add(col);
        for(var path:polynomial.mainEffects())if(binary.contains(path.target()))throw new IllegalArgumentException("Binary covariates must be exogenous roots, not modeled continuous outcomes.");
        for(int column:binary)for(var row:data)if(row[column]!=0&&row[column]!=1)throw new IllegalArgumentException("Binary covariates must be explicitly coded 0/1; recode before fitting.");
        List<Equation> equations=new ArrayList<>();Set<Integer> fitted=new HashSet<>();
        for(var base:polynomial.equations()){
            Matrices.interrupted();var correction=corrections.get(base.target());Controls controls;
            if(correction==null)controls=new Controls(List.of(),new double[data.length][0],List.of());
            else{Set<Integer> variables=new HashSet<>();for(var term:base.regressors())for(int factor:term.factors())variables.add(factor);Set<Integer> classified=new HashSet<>();for(var values:List.of(correction.endogenous,correction.continuousExogenous,correction.binaryExogenous))for(int column:values)classified.add(column);if(!variables.equals(classified))throw new IllegalArgumentException("Classify every structural predictor exactly once as continuous endogenous, continuous exogenous, or binary exogenous for target "+model.names.get(base.target())+".");List<String> expected=reference==null?null:reference.equations.stream().filter(e->e.target==base.target()).findFirst().orElseThrow().controls.groups.stream().map(Group::label).toList();controls=controls(data,model.names,correction,expected);fitted.add(base.target());}
            if((long)data.length*(base.regressors().size()+controls.names.size()+1)>5000000L)throw new IllegalArgumentException("Augmented copula equation exceeds five million design cells.");
            double[][] x=new double[data.length][base.regressors().size()+controls.names.size()];double[] y=new double[data.length];
            for(int row=0;row<data.length;row++){y[row]=data[row][base.target()];for(int term=0;term<base.regressors().size();term++){double value=1;for(int factor:base.regressors().get(term).factors())value*=data[row][factor];x[row][term]=value;}System.arraycopy(controls.values[row],0,x[row],base.regressors().size(),controls.names.size());}
            double condition=condition(x);var regression=OlsRegression.fit(x,y);double[] predictions=new double[y.length],residuals=new double[y.length];for(int i=0;i<y.length;i++){predictions[i]=regression.predict(x[i]);residuals[i]=y[i]-predictions[i];}
            equations.add(new Equation(base.target(),base.regressors(),correction,regression.coefficients(),base.coefficients(),controls,regression.residualDegreesOfFreedom(),regression.residualSumOfSquares(),regression.rSquared(),regression.adjustedRSquared(),condition,predictions,residuals));
        }
        if(!fitted.equals(corrections.keySet()))throw new IllegalArgumentException("Every corrected target needs a structural equation.");
        List<String> warnings=new ArrayList<>();warnings.add("Adjusted empirical CDF uses equation 9's <= count (upper rank for ties), not midranks. Equation 17/21 uses the inverse sample covariance of endogenous and exogenous continuous normal scores. Controls retain this explicit basis, including when no continuous exogenous variable is selected.");warnings.add("Copula identification requires substantive exogeneity and joint-normal rank/error assumptions, adequate non-normality, full-rank designs and sufficient observations in each category. A non-significant control is not proof that endogeneity is absent.");warnings.add("Only selected equations are corrected. Structural-polynomial derivatives hold generated error controls fixed and are not augmented conditional-mean derivatives or an automatic causal claim. Binary covariate derivatives are omitted; use category-specific predictions for discrete changes.");warnings.add("Point-fit classical generated-regressor standard errors are deliberately omitted. Use full-pipeline case bootstrap; observations must be independent for the supplied IID resampling contract.");
        if(model.corrections.stream().anyMatch(c->c.binaryExogenous.length>0&&!c.varyingByCategory))warnings.add("A common copula structure across binary categories is imposed for one or more equations; this restriction requires theoretical support.");
        if(equations.stream().flatMap(e->e.controls.groups.stream()).anyMatch(g->g.observations<30))warnings.add("One or more categories contain fewer than 30 cases; adjusted empirical-CDF inference can remain unstable in small groups.");
        if(equations.stream().anyMatch(e->e.standardizedConditionNumber>1000))warnings.add("One or more augmented designs have standardized condition number above 1000; weak non-normal identification or collinearity may make inference unstable.");
        return new Fit(model,data.length,polynomial.mainEffects(),equations,effects(data,model,equations,binary),warnings);
    }
    private static Controls controls(double[][] data,List<String> names,Correction correction,List<String> expected){
        List<Integer> continuous=new ArrayList<>();for(int column:correction.endogenous)continuous.add(column);for(int column:correction.continuousExogenous)continuous.add(column);int q=continuous.size(),k=correction.endogenous.length;
        Map<String,List<Integer>> groups=new TreeMap<>();for(int row=0;row<data.length;row++){String label="All";if(correction.varyingByCategory&&correction.binaryExogenous.length>0){StringJoiner joined=new StringJoiner(",");for(int column:correction.binaryExogenous)joined.add(Integer.toString((int)data[row][column]));label=joined.toString();}groups.computeIfAbsent(label,key->new ArrayList<>()).add(row);}
        List<String> labels=List.copyOf(groups.keySet());if(expected!=null&&!labels.equals(expected))throw new IllegalArgumentException("A resample lost an expected binary category; coefficient schema was preserved by rejecting the fit.");
        if((long)data.length*labels.size()*k>5000000L)throw new IllegalArgumentException("Category-specific control matrix exceeds five million cells.");
        double[][] values=new double[data.length][labels.size()*k];List<String> controlNames=new ArrayList<>();List<Group> diagnostics=new ArrayList<>();int groupIndex=0;
        for(var entry:groups.entrySet()){
            Matrices.interrupted();var rows=entry.getValue();int n=rows.size();if(n<Math.max(8,q+3))throw new IllegalArgumentException("Too few cases for conditional normal-score covariance in category "+entry.getKey()+".");double[][] z=new double[n][q];
            for(int c=0;c<q;c++){double[] original=new double[n];for(int i=0;i<n;i++)original[i]=data[rows.get(i)][continuous.get(c)];double[] ranked=adjustedScores(original);for(int i=0;i<n;i++)z[i][c]=ranked[i];}
            double[] means=new double[q];for(var row:z)for(int c=0;c<q;c++)means[c]+=row[c]/n;double[][] covariance=new double[q][q];for(var row:z)for(int a=0;a<q;a++)for(int b=0;b<q;b++)covariance[a][b]+=(row[a]-means[a])*(row[b]-means[b])/(n-1);
            var decomposition=new SingularValueDecomposition(new Array2DRowRealMatrix(covariance,false));double condition=decomposition.getConditionNumber();if(decomposition.getRank()!=q||!Double.isFinite(condition)||condition>1e10)throw new IllegalArgumentException("Conditional normal-score covariance is singular or ill-conditioned in category "+entry.getKey()+".");double[][] inverse=decomposition.getSolver().getInverse().getData();
            for(int i=0;i<n;i++)for(int target=0;target<k;target++)for(int c=0;c<q;c++)values[rows.get(i)][groupIndex*k+target]+=z[i][c]*inverse[c][target];
            for(int target=0;target<k;target++)controlNames.add("Adjusted GC: "+names.get(correction.endogenous[target])+" ["+entry.getKey()+"]");diagnostics.add(new Group(entry.getKey(),n,condition));groupIndex++;
        }
        return new Controls(controlNames,values,diagnostics);
    }
    /** Exposed for reproducibility/diagnostics. Ties use the empirical <= count. */
    public static double[] adjustedScores(double[] input){int n=input.length;if(n<3)throw new IllegalArgumentException("At least three continuous observations are required.");Integer[] order=new Integer[n];for(int i=0;i<n;i++){if(!Double.isFinite(input[i]))throw new IllegalArgumentException("Rank input must be finite.");order[i]=i;}Arrays.sort(order,Comparator.comparingDouble(i->input[i]));double[] result=new double[n];int distinct=0;var normal=new NormalDistribution();for(int start=0;start<n;){Matrices.interrupted();int end=start+1;while(end<n&&input[order[end]]==input[order[start]])end++;double probability=.5/n+(n-1.0)*end/((double)n*n),value=normal.inverseCumulativeProbability(probability);for(int i=start;i<end;i++)result[order[i]]=value;distinct++;start=end;}if(distinct<3)throw new IllegalArgumentException("Selected continuous variable has fewer than three distinct values in a category.");return result;}
    private static double condition(double[][] x){int p=Matrices.width(x,3);double[][] design=new double[x.length][p+1];for(var row:design)row[0]=1;for(int column=0;column<p;column++){double mean=0,variance=0;for(var row:x)mean+=row[column]/x.length;for(var row:x)variance+=(row[column]-mean)*(row[column]-mean)/x.length;if(!(variance>0)||!Double.isFinite(variance))throw new IllegalArgumentException("Constant or nonfinite augmented copula design column.");for(int row=0;row<x.length;row++)design[row][column+1]=(x[row][column]-mean)/Math.sqrt(variance);}var svd=new SingularValueDecomposition(new Array2DRowRealMatrix(design,false));double value=svd.getConditionNumber();if(svd.getRank()!=p+1||!Double.isFinite(value)||value>1e10)throw new IllegalArgumentException("Augmented copula model is rank deficient or numerically unidentified.");return value;}
    private static List<Effect> effects(double[][] data,Model model,List<Equation> equations,Set<Integer> binary){int m=model.names.size();List<PathProcess.Probe> probes=model.probes;if(probes.isEmpty()){Map<Integer,Double> means=new LinkedHashMap<>();for(int c=0;c<m;c++){double mean=0;for(var row:data)mean+=row[c]/data.length;means.put(c,mean);}probes=List.of(new PathProcess.Probe("Observed means",means));}List<Effect> out=new ArrayList<>();Set<String> seen=new HashSet<>();for(var probe:probes){if(probe.name()==null||probe.name().isBlank()||!seen.add(probe.name()))throw new IllegalArgumentException("Probe names must be nonempty and unique.");double[] at=new double[m];for(var value:probe.values().entrySet()){if(value.getKey()<0||value.getKey()>=m||!Double.isFinite(value.getValue()))throw new IllegalArgumentException("Invalid structural probe.");at[value.getKey()]=value.getValue();}double[][] jacobian=new double[m][m];for(var equation:equations)for(int j=0;j<equation.terms.size();j++){int[] factors=equation.terms.get(j).factors();for(int omitted=0;omitted<factors.length;omitted++){double derivative=equation.coefficients[j+1];for(int k=0;k<factors.length;k++)if(k!=omitted)derivative*=at[factors[k]];jacobian[factors[omitted]][equation.target]+=derivative;}}var direct=new Array2DRowRealMatrix(jacobian,false);var total=new LUDecomposition(MatrixUtils.createRealIdentityMatrix(m).subtract(direct)).getSolver().getInverse().subtract(MatrixUtils.createRealIdentityMatrix(m));for(int source=0;source<m;source++)if(!binary.contains(source))for(int target=0;target<m;target++)if(source!=target){double d=jacobian[source][target],t=total.getEntry(source,target);if(!Double.isFinite(d)||!Double.isFinite(t))throw new IllegalArgumentException("Structural derivatives exceed the finite numerical range.");out.add(new Effect(probe.name(),"Direct structural derivative",source,target,d));out.add(new Effect(probe.name(),"Total structural derivative",source,target,t));out.add(new Effect(probe.name(),"Indirect structural derivative",source,target,t-d));}if(out.size()>10000)throw new IllegalArgumentException("Too many structural derivative targets; reduce probes/model size.");}return List.copyOf(out);}
    public static Resampled bootstrap(double[][] data,Model model,Bootstrap.Options options,IntConsumer progress){Fit point=fit(data,model);List<Bootstrap.Parameter> parameters=parameters(point);var wald=new CopulaWald.Accumulator(point,options.samples());var inference=Resampling.run(data,parameters,values(point),options,(sample,rows)->{double[] values=values(refit(sample,point.model,point));if(sample.length==data.length)wald.accept(values);return values;},progress,"Adjusted empirical-CDF Gaussian copula system","Each shared case/jackknife draw recomputes structural products, category memberships, upper ranks, adjusted CDFs, conditional covariance inverses, generated controls, all equations and structural derivatives. Missing categories fail without changing the parameter schema.");List<String>warnings=new ArrayList<>(inference.warnings());warnings.addAll(point.warnings);inference=new Bootstrap.Result(inference.options(),inference.method(),inference.randomGenerator(),inference.signHandling(),inference.successful(),inference.failed(),inference.failures(),inference.estimates(),warnings,inference.estimator());return new Resampled(point,inference,wald.finish(inference.successful()));}
    public static List<Bootstrap.Parameter> parameters(Fit fit){List<Bootstrap.Parameter> out=new ArrayList<>();for(var equation:fit.equations){out.add(new Bootstrap.Parameter("Structural intercept",-1,equation.target,-1,fit.model.names.get(equation.target)));for(int j=0;j<equation.terms.size();j++)out.add(new Bootstrap.Parameter(equation.correction==null?"Uncorrected structural":"Corrected structural",-1,equation.target,j,label(equation.terms.get(j),fit.model.names)));for(int j=0;j<equation.controls.names.size();j++)out.add(new Bootstrap.Parameter("Adjusted copula control",-1,equation.target,j,equation.controls.names.get(j)));}for(var effect:fit.effects)out.add(new Bootstrap.Parameter(effect.family,effect.source,effect.target,-1,effect.probe));return List.copyOf(out);}
    public static String label(NonlinearPls.Regressor term,List<String> names){StringJoiner out=new StringJoiner(" × ");for(int factor:term.factors())out.add(names.get(factor));return out.toString();}
    public static double[] values(Fit fit){List<Double> out=new ArrayList<>();for(var equation:fit.equations)for(double value:equation.coefficients)out.add(value);for(var effect:fit.effects)out.add(effect.value);return out.stream().mapToDouble(Double::doubleValue).toArray();}
}
